/**
 * Model Person
 * [EXISTENTE] RF-01 / RF-02 - Persona física base (usuarios, propietarios, representantes)
 */
export type Person = $Result.DefaultSelection<Prisma.$PersonPayload>
/**
 * Model User
 * [EXISTENTE] RF-01 - Credenciales de acceso
 * [NUEVO] roleId, status, campos de recuperación/2FA se agregan vía relaciones abajo (B.1)
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Propietary
 * [EXISTENTE] Dueño de una institución (empresa)
 */
export type Propietary = $Result.DefaultSelection<Prisma.$PropietaryPayload>
/**
 * Model Represent
 * [EXISTENTE] RF-03 - Representante de una empresa (legal / calidad / contacto)
 * [NUEVO] institutionId + tipo: hoy solo enlaza a person; el SRS pide 3 tipos de
 * representante por empresa (Legal, Calidad, Contacto principal).
 */
export type Represent = $Result.DefaultSelection<Prisma.$RepresentPayload>
/**
 * Model Institution
 * [EXISTENTE] RF-03 - Empresa / establecimiento
 * [NUEVO] nombreComercial, actividadEconomica, municipalityId reemplazan los
 * campos libres de municipio/provincia del SRS por catálogo normalizado.
 */
export type Institution = $Result.DefaultSelection<Prisma.$InstitutionPayload>
/**
 * Model InstitutionStatus
 * [EXISTENTE] Estado / certificación vigente de una institución
 */
export type InstitutionStatus = $Result.DefaultSelection<Prisma.$InstitutionStatusPayload>
/**
 * Model InstitutionStatusQuestion
 * [EXISTENTE]
 */
export type InstitutionStatusQuestion = $Result.DefaultSelection<Prisma.$InstitutionStatusQuestionPayload>
/**
 * Model SaPermit
 * [EXISTENTE] Permiso Sanitario
 */
export type SaPermit = $Result.DefaultSelection<Prisma.$SaPermitPayload>
/**
 * Model Category
 * [EXISTENTE] Categoría de alimento
 */
export type Category = $Result.DefaultSelection<Prisma.$CategoryPayload>
/**
 * Model SubCategory
 * [EXISTENTE] RF-14 - Subcategoría con nivel de riesgo (Matriz_Riesgo_Alimentos.xlsx)
 */
export type SubCategory = $Result.DefaultSelection<Prisma.$SubCategoryPayload>
/**
 * Model Food
 * [EXISTENTE]
 */
export type Food = $Result.DefaultSelection<Prisma.$FoodPayload>
/**
 * Model FormTemplate
 * [EXISTENTE] Plantilla de ficha (ej. "Ficha Inspección BPM v1.00")
 */
export type FormTemplate = $Result.DefaultSelection<Prisma.$FormTemplatePayload>
/**
 * Model FormResponse
 * [EXISTENTE] RF-12/RF-13 - Ficha diligenciada (respuestas en JSONB)
 */
export type FormResponse = $Result.DefaultSelection<Prisma.$FormResponsePayload>
/**
 * Model H1
 * [EXISTENTE] Nivel 1 de la jerarquía de la ficha (ej. "1. ESTABLECIMIENTO")
 */
export type H1 = $Result.DefaultSelection<Prisma.$H1Payload>
/**
 * Model H1Ask
 * [EXISTENTE]
 */
export type H1Ask = $Result.DefaultSelection<Prisma.$H1AskPayload>
/**
 * Model H2
 * [EXISTENTE] Nivel 2 (ej. "1.1 Ubicación y estructura")
 */
export type H2 = $Result.DefaultSelection<Prisma.$H2Payload>
/**
 * Model H2Ask
 * [EXISTENTE]
 */
export type H2Ask = $Result.DefaultSelection<Prisma.$H2AskPayload>
/**
 * Model H3
 * [EXISTENTE] Nivel 3 (ej. "1.1.1 Ubicación del establecimiento")
 */
export type H3 = $Result.DefaultSelection<Prisma.$H3Payload>
/**
 * Model H3Ask
 * [EXISTENTE]
 */
export type H3Ask = $Result.DefaultSelection<Prisma.$H3AskPayload>
/**
 * Model H4
 * [EXISTENTE] Nivel 4 (ej. "1.1.3.1 Paredes")
 */
export type H4 = $Result.DefaultSelection<Prisma.$H4Payload>
/**
 * Model H4Ask
 * [EXISTENTE]
 */
export type H4Ask = $Result.DefaultSelection<Prisma.$H4AskPayload>
/**
 * Model AskAuditory
 * [EXISTENTE] Bitácora de cambios sobre una pregunta (h_id genérico + h_num)
 */
export type AskAuditory = $Result.DefaultSelection<Prisma.$AskAuditoryPayload>
/**
 * Model Role
 * RF-02 - catálogo de roles (Administrador, Administrador Empresa, Usuario
 * Delegado, Coordinador, Técnico Evaluador) usado para RBAC (RNF-02)
 */
export type Role = $Result.DefaultSelection<Prisma.$RolePayload>
/**
 * Model PasswordResetToken
 * RF-01 - Recuperación de contraseña
 */
export type PasswordResetToken = $Result.DefaultSelection<Prisma.$PasswordResetTokenPayload>
/**
 * Model TwoFactorAuth
 * RF-01 - Doble factor de autenticación (opcional)
 */
export type TwoFactorAuth = $Result.DefaultSelection<Prisma.$TwoFactorAuthPayload>
/**
 * Model Province
 * 
 */
export type Province = $Result.DefaultSelection<Prisma.$ProvincePayload>
/**
 * Model Municipality
 * 
 */
export type Municipality = $Result.DefaultSelection<Prisma.$MunicipalityPayload>
/**
 * Model HealthArea
 * Catálogo "Área de Salud" (I a VIII) visto en la Ficha BPM
 */
export type HealthArea = $Result.DefaultSelection<Prisma.$HealthAreaPayload>
/**
 * Model Attachment
 * Tabla genérica de adjuntos; se relaciona opcionalmente con cada entidad
 * que puede recibir archivos (una sola de las FKs va poblada por registro).
 */
export type Attachment = $Result.DefaultSelection<Prisma.$AttachmentPayload>
/**
 * Model BpmRequest
 * 
 */
export type BpmRequest = $Result.DefaultSelection<Prisma.$BpmRequestPayload>
/**
 * Model Case
 * RF-06/RF-10/RF-19 - Expediente: unifica el origen (solicitud, programación,
 * alerta o denuncia), la asignación de coordinador/técnico y el cierre.
 */
export type Case = $Result.DefaultSelection<Prisma.$CasePayload>
/**
 * Model LapchAlert
 * 
 */
export type LapchAlert = $Result.DefaultSelection<Prisma.$LapchAlertPayload>
/**
 * Model Complaint
 * 
 */
export type Complaint = $Result.DefaultSelection<Prisma.$ComplaintPayload>
/**
 * Model Assignment
 * 
 */
export type Assignment = $Result.DefaultSelection<Prisma.$AssignmentPayload>
/**
 * Model Evaluation
 * Envuelve la ficha (FormResponse ya existente) con programación, técnico
 * asignado y estado del proceso de campo.
 */
export type Evaluation = $Result.DefaultSelection<Prisma.$EvaluationPayload>
/**
 * Model RiskFrequencyRule
 * Tabla de referencia estática = "Matriz de Frecuencia de Inspección" del SRS
 * (1.0-3.6 => Bajo/Anual, >3.6-6.3 => Medio/Semestral, >6.3 => Alto/Trimestral)
 */
export type RiskFrequencyRule = $Result.DefaultSelection<Prisma.$RiskFrequencyRulePayload>
/**
 * Model EvaluationScore
 * Resultado calculado automáticamente por evaluación (puntaje, % cumplimiento, nivel)
 */
export type EvaluationScore = $Result.DefaultSelection<Prisma.$EvaluationScorePayload>
/**
 * Model Evidence
 * 
 */
export type Evidence = $Result.DefaultSelection<Prisma.$EvidencePayload>
/**
 * Model EvaluationReport
 * RF-16 - Informe generado automáticamente a partir de la evaluación
 */
export type EvaluationReport = $Result.DefaultSelection<Prisma.$EvaluationReportPayload>
/**
 * Model ReportReview
 * RF-17/RF-18 - Cada acción del coordinador sobre un informe (y su posterior
 * corrección/reenvío por parte del técnico)
 */
export type ReportReview = $Result.DefaultSelection<Prisma.$ReportReviewPayload>
/**
 * Model Notification
 * 
 */
export type Notification = $Result.DefaultSelection<Prisma.$NotificationPayload>

